import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

/* eslint-disable re-lint/no-duplicate-code -- this real-socket harness deliberately mirrors the resume acceptance harness. */
/* eslint-disable re-lint/prefer-early-return -- the message barrier keeps the socket assertions readable. */

// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
}

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];
const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

beforeEach(() => {
  logLines.length = 0;
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
  setLogger();
});

const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: userId}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') {
        connected = frame;
        client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      frames.push(frame);
    });
  });
  return {connected, frames};
};

// A store with only the five required members, so listFor can be omitted, recorded or made to throw.
const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const inner = new InMemorySessionStore();
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return summaries;
      },
    };
    const url = await startEngine(store, 'u1');
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, frames}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const withoutList = await startEngine(delegatingTo(inner));
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

    expect({
      unimplemented: unimplemented.frames,
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const inner = new InMemorySessionStore();
    let calls = 0;
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: () => {
        calls += 1;
        return [];
      },
    };
    const url = await startEngine(store);
    const badFrames = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const codes: Array<string | undefined> = [];
    for (const bad of badFrames) {
      const {frames} = await askAfterConnect(url, bad);
      codes.push(frames[0]?.code);
    }
    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: [{type: 'session_list', sessions: []}],
      calls: 1,
    });
  });
});

import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a list_sessions frame and forwards only its paging fields', () => {
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};

    const result = validateMessage({type: 'list_sessions', limit: 10, before, userId: 'someone-else'});

    expect(result).toEqual({valid: true, data: {type: 'list_sessions', limit: 10, before}});
  });
});
import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {SessionResumeOptions} from './ws/sessionResume.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ConnectedMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what a reconnect is sent is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  resumeFailure?: string;
  index?: number;
  entry?: SessionEntry;
}

const NEVER_ISSUED = '0f1e2d3c-4b5a-4968-8776-655443322110';
const RESUME_ON: SessionResumeOptions = {enabled: true};
const LATEST_ON: SessionResumeOptions = {enabled: true, latest: true};
const HALF_ANSWER: SessionEntry = {
  role: 'assistant',
  content: 'half',
  timestamp: '2026-09-30T08:00:01.000Z',
  isStreaming: true,
};

// A tool's suppression lands while the answer is still open, as when a provider ends a tool round with no stop.
const suppressingMidAnswer: ChatOrchestrator = {
  processMessage: async () => 'before after',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'before'};
    yield {type: 'suppress_output'} as unknown as MessageChunk;
    yield {type: 'text', text: ' after'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

// Silenced for the whole file: the server logs every connection and close, and these tests read frames, not logs.
beforeAll(() => {
  setLogger({debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined});
});

afterAll(() => {
  setLogger();
});

// Each server sees its sockets close before it stops, so no close is logged after the logger above is restored.
afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
});

// The authenticated user is read per upgrade, so one test can reconnect as someone else.
const startEngine = async (
  store: SessionStore,
  resume?: SessionResumeOptions,
  orchestrator: ChatOrchestrator = answeringOrchestrator
) => {
  const auth = {userId: 'u1'};
  const connects: Array<{sessionId: string; resumed: boolean}> = [];
  const disconnected: string[] = [];
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: auth.userId}),
    sessionStore: store,
    orchestrator,
    resume,
    onConnect: (session, {resumed}) => void connects.push({sessionId: session.sessionId, resumed}),
    onDisconnect: sessionId => void disconnected.push(sessionId),
  });
  // Resolves once the server itself has seen its first socket close, which the client's own close can precede.
  const firstServerClose = new Promise<void>(resolve => {
    hal.wss.once('connection', socket => socket.once('close', () => resolve()));
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {auth, connects, disconnected, firstServerClose, base: `ws://127.0.0.1:${port}/hal/ws`};
};

const open = (url: string, token = 't'): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
};

// One question answered and the socket closed, returning the id the connected frame announced.
const firstTurn = async (base: string): Promise<string> => {
  const client = open(base);
  let sessionId = '';
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
      if (frame.type === 'stream_end') resolve();
    });
  });
  client.close();
  await once(client, 'close');
  return sessionId;
};

// A ping sent on connect is a barrier: its pong can only follow every frame the replay wrote.
const connectAndSettle = async (url: string, token?: string): Promise<Frame[]> => {
  const client = open(url, token);
  const frames: Frame[] = [];
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      frames.push(frame);
      if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      if (frame.type === 'pong') resolve();
    });
  });
  return frames;
};

const upserts = (frames: Frame[]) =>
  frames.filter(frame => frame.type === 'entry_upsert').map(({index, entry}) => ({index, entry}));

const shapeOf = (frames: Frame[]) => ({
  keys: Object.keys(frames[0]).sort(),
  resumed: frames[0].resumed,
  resumeFailure: frames[0].resumeFailure,
  types: frames.map(frame => frame.type),
});

const deferredRelease = () => {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release: () => release()};
};

// Each stored conversation holds one user entry, sent at the given time and reading as its own id.
const storeWith = (conversations: Array<[sessionId: string, userId: string, sentAt: string]>): InMemorySessionStore => {
  const store = new InMemorySessionStore();
  for (const [sessionId, userId, sentAt] of conversations) {
    const {entries} = store.create(sessionId, userId);
    entries.push({role: 'user', content: sessionId, timestamp: sentAt});
  }
  return store;
};

// A store with only the required members, so an optional one can be added, replaced or left out per test.
const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

describe('resuming a conversation on reconnect', () => {
  it('with resume absent, answers a reconnect naming the first id with a new id and no replay', async () => {
    const {base} = await startEngine(new InMemorySessionStore());
    const first = await firstTurn(base);

    const frames = await connectAndSettle(`${base}?sessionId=${first}`);

    expect({newId: frames[0].sessionId !== first, shape: shapeOf(frames)}).toEqual({
      newId: true,
      shape: {
        keys: ['examplePrompts', 'message', 'sessionId', 'type'],
        resumed: undefined,
        types: ['connected', 'pong'],
      },
    });
  });

  it('with resume on, answers the owner reconnecting with resumed true, entryCount 2 and both stored entries', async () => {
    const store = new InMemorySessionStore();
    const {base} = await startEngine(store, RESUME_ON);
    const first = await firstTurn(base);

    const frames = await connectAndSettle(`${base}?sessionId=${first}`);

    const stored = JSON.parse(JSON.stringify((await store.get(first))?.entries)) as SessionEntry[];
    expect({connected: frames[0], replay: upserts(frames)}).toMatchObject({
      connected: {type: 'connected', sessionId: first, resumed: true, entryCount: 2},
      replay: [
        {index: 0, entry: stored[0]},
        {index: 1, entry: stored[1]},
      ],
    });
  });

  it('answers another user naming the id exactly as it answers an id that was never issued', async () => {
    const {auth, base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
    const first = await firstTurn(base);
    auth.userId = 'u2';

    const otherUser = await connectAndSettle(`${base}?sessionId=${first}`);
    const neverIssued = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);

# Conversation List

| Field  | Value                 |
| ------ | --------------------- |
| Issue  | re-cinq/HALEngine#143 |
| Status | Shipped               |

Resume gets a client back into one conversation: the id it names, or the user's most recently active one. Neither tells it which conversations exist, and every other member of `SessionStore` answers about a session the caller can already name, so a consumer wanting to offer a conversation list had to query the collection behind the engine's back, against a document shape and a key the engine owns. `listFor` answers the list instead, as summaries rather than sessions. **GDPR.** A summary is personal data — that a user held a conversation, and when — so it carries no conversation content, it is filtered to one user by the query rather than in application code afterwards, and the retention bound stays the consumer's, through the store's `maxAgeMs` and erasure methods and re-cinq/HALEngine#41.

## The summary

- A summary is `sessionId`, `createdAt`, `updatedAt` and `entryCount`, and nothing else: neither the conversation's entries nor its credentials, so a list can never hand over either, even for a session created with credentials ([validated by: carries only its four fields, so a list can never hand over a conversation or a credential](../../src/infrastructure/stores/sessionStoreListSignature.test.ts#L22)).
- `listFor` is optional, like `latestFor` and `lookup` before it: a store written against the five original members still satisfies the interface, and both shipped stores implement it ([validated by: leaves a store with only the five original members satisfying the interface beside both shipped ones](../../src/infrastructure/stores/sessionStoreListSignature.test.ts#L11)).

## The order a list answers in

- Summaries come back most recent activity first ([validated by: answers newest activity first, headed by the very session latestFor returns](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L27)).
- The first summary is the session `latestFor` returns, because both read the same activity ([validated by: answers newest activity first, headed by the very session latestFor returns](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L27)).
- The order is total rather than merely sorted: two conversations last active in the same millisecond are ordered by session id, the larger first, which is what lets a page resume without dropping one of them ([validated by: keeps a conversation tied on activity rather than dropping it across a page boundary](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L141)).
- In `InMemorySessionStore` that tie-break is the list's alone: `latestFor` breaks the same tie by creation order, so for two tied conversations the head of the list and the session a resume rejoins can differ ([validated by: breaks a tie on activity by session id, where latestFor takes the session created later](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L42)).
- `MongoSessionStore` answers in order of `updatedAt`, which each `save` moves forward, and its first summary is the session its own `latestFor` returns ([validated by: answers the user's conversations newest saved first, headed by the one latestFor returns](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L31)).
- It breaks a tie by `_id` in both members, so there the head of the list is the session a resume rejoins even when every conversation shares an `updatedAt` ([validated by: heads the list with the session latestFor returns even when every conversation shares an updatedAt](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L161)).

## What a summary reports

- `InMemorySessionStore` reports the moment `create` was called, the newest entry time as the activity, and the conversation's entry count ([validated by: reports a creation time, the newest activity and the entry count of each conversation](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L53)).
- `MongoSessionStore` reports the document's `createdAt`, the `updatedAt` its last save wrote, and the counter written beside the entries ([validated by: reports the creation time, the last save and the entry count of each conversation](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L49)).
- That counter is what a save writes, so a list never reads a conversation to count one ([validated by: counts a conversation from the field a save writes beside the entries](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L95)).
- A document written before the counter existed reads as a conversation of no entries rather than failing the list, which is what the backlog documented in `docs/session-stores.md` is for ([validated by: reads a conversation saved before the counter existed as one of no entries, rather than failing](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L79)).

## Whose conversations

- A list holds only the asking user's conversations: another user's never appear, and a user with none gets an empty list ([validated by: omits a conversation that aged out and another user's, and answers nothing for a user with none](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L65)).
- `InMemorySessionStore` omits a conversation that has aged out, as `latestFor` does ([validated by: omits a conversation that aged out and another user's, and answers nothing for a user with none](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L65)).
- `MongoSessionStore` filters on the user in the database, sorts on `{updatedAt: -1, _id: -1}` — the `{userId: 1, updatedAt: -1}` index `latestFor` already needs serves its leading keys — and asks for a projection that leaves the entries behind ([validated by: asks the database to filter on the user, sort on the index with the id behind it, and never for the entries](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L108)).
- It answers from that projection alone, so a collection that never returns an entry still lists conversations — the conversation does not leave the database to be listed ([validated by: answers from a projection alone, so a collection that never returns entries still lists conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L181)).

## Paging

- `limit` takes that many of the newest, and `before` resumes after a row, so a client pages by passing back the last summary it saw — `SessionCursor` is `updatedAt` and `sessionId`, which a `SessionSummary` already satisfies ([validated by: pages down the same order: a limit takes the newest, and before takes what is older than it](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L78)).
- Paging walks every conversation exactly once even when all of them share an activity time, because the cursor carries the session id the order breaks ties on: a tie cannot fall between two pages and be skipped ([validated by: keeps a conversation tied on activity rather than dropping it across a page boundary](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L141)).
- `MongoSessionStore` pages the same way ([validated by: pages with before and a limit, down the same newest-first order](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L62)).
- It walks a tie exactly once too, through the same cursor ([validated by: keeps a conversation tied on updatedAt rather than dropping it across a page boundary](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L127)).
- A list is at most 200 summaries however many are asked for, and 50 when none is asked for, so no caller can ask for an unbounded page ([validated by: answers at most two hundred conversations however many are asked for, and fifty when none is](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L94)).
- That limit bounds the rows answered, not the rows the database reads to answer them: on `MongoSessionStore` the work is bounded by the `{userId: 1, updatedAt: -1, _id: -1}` index `docs/session-stores.md` prescribes, and under the two-key form Mongo sorts the user's whole history before applying the limit ([validated by: needs the three-key index to answer without sorting the whole history, which the two-key form does not](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L192)).
- A fractional limit is floored rather than refused, since a slip in a limit is not a reason to deny a user their history ([validated by: floors a fractional limit, and reads a negative or unusable one as none given rather than as nothing](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L104)).
- A negative limit, and one that is not a usable number, are read as no limit given at all rather than as a limit of none: handing a user an empty history for a typo is the worse reading ([validated by: floors a fractional limit, and reads a negative or unusable one as none given rather than as nothing](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L104)).
- Only a limit of exactly `0` answers no conversations ([validated by: answers nothing only for a limit of exactly none](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L116)).
- `MongoSessionStore` answers a limit of `0` without querying, because MongoDB reads `limit: 0` as no limit at all and would otherwise answer with every conversation the filter matches ([validated by: answers a limit of none without asking the database, which reads a limit of zero as no limit at all](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L143)).

## The two shipped stores answer one order

- `InMemorySessionStore` and `MongoSessionStore` list the same conversations in the same order, so a consumer swapping one for the other sees the same conversation list ([validated by: answer the same order for conversations whose activity differs](../../src/infrastructure/stores/storeListAgreement.test.ts#L43)).
- They break a tie on activity the same way, by session id ([validated by: break a tie on activity the same way, by session id](../../src/infrastructure/stores/storeListAgreement.test.ts#L52)).
- They page identically through the documented call, `listFor(userId, {limit, before: rows.at(-1)})`, a page at a time until a page comes back empty ([validated by: page the same way through the documented call, two rows at a time from the last row seen](../../src/infrastructure/stores/storeListAgreement.test.ts#L61)).

## A cursor the caller can actually hold

- A cursor's `updatedAt` may be a `Date`, an ISO string or an epoch number, so a summary that went through JSON on its way to a client and back still pages ([validated by: pages on a cursor that has been through JSON, and refuses one carrying no usable moment](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L123)).
- `MongoSessionStore` reads such a cursor as a date before it queries, since a string compares against no stored BSON date and would quietly match none of them ([validated by: pages on a cursor that has been through JSON, where a string would have matched no stored date](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L150)).
- A cursor carrying no usable moment is refused with an error naming it, rather than read as no cursor at all, which would answer the first page again and repeat rows a client has already shown ([validated by: pages on a cursor that has been through JSON, and refuses one carrying no usable moment](../../src/infrastructure/stores/inMemoryConversationList.test.ts#L123)).

## A collection that cannot list

- `find` is optional on `CollectionLike`, so an adapter written before conversation lists existed still satisfies the port ([validated by: refuses to list on a collection that implements no find, rather than reporting no conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L175)).
- A store built on a collection without it refuses to list, rather than reporting that the user has no conversations ([validated by: refuses to list on a collection that implements no find, rather than reporting no conversations](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L175)).

## When the store cannot answer

- A store whose collection fails rejects rather than answering a partial or empty list: what to show a user who may have conversations is the caller's decision, and an empty history is not a safe guess ([validated by: rejects rather than answering a partial list when the collection fails](../../src/infrastructure/stores/mongo/mongoConversationList.test.ts#L225)).

## Over the WebSocket protocol

The WebSocket history feature is opt-in through `transport.history`. When enabled, the client
can request a user's summaries with `list_sessions`; the response carries metadata only and
the user id always comes from the authenticated connection, never from the frame.

- A client sends `{type: 'list_sessions', limit?, before?}` and receives `{type: 'session_list', sessions}` for the socket's authenticated user, with `createdAt` and `updatedAt` serialised as ISO-8601 strings and any client-supplied `userId` ignored ([validated by: answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId](../../src/transport/conversationList.acceptance.test.ts#L96), [validated by: answers list_sessions from the session store without entering the turn lock](../../src/transport/ws/messageHandler.test.ts#L98)).
- A store without `listFor` answers `{type: 'session_list', sessions: []}`, and a throwing `listFor` logs an error on the `ws` category and answers `{type: 'error', code: 'SERVER_ERROR'}` ([validated by: answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws](../../src/transport/conversationList.acceptance.test.ts#L137)).
- The validator accepts an optional non-negative integer `limit` and an optional `before` cursor whose `sessionId` is 1–128 characters and whose `updatedAt` parses as a valid timestamp, rejecting any other `list_sessions` payload with `INVALID_MESSAGE` without calling `listFor` ([validated by: accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor](../../src/transport/conversationList.acceptance.test.ts#L166), [validated by: accepts a list_sessions frame and forwards only its paging fields](../../src/transport/ws/validation.test.ts#L24)).
import type {SessionEntry} from './session.js';
import type {SessionCursor, SessionSummary} from './sessionStore.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: SessionCursor;
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionSummaryFrame extends Omit<SessionSummary, 'createdAt' | 'updatedAt'> {
  createdAt: string;
  updatedAt: string;
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage;

export {ErrorCodes} from './session.js';
